+fn add_adaptive(c: &mut Client, plate_top: &str, method: &str, load: Option<f64>) -> String {
+    let mut params = json!({
+        "method": method,
+        "stepdown": 14.0,
+        "stock_to_leave": 0.5,
+        "top_z": { "reference": "fixed", "offset": 24.0 },
+        "bottom_z": { "reference": "fixed", "offset": 10.0 },
+        "clearance_z": { "reference": "fixed", "offset": 35.0 },
