+fn protected_spiral(tag: &str, plate: [f64; 4], load: Option<f64>) -> (std::path::PathBuf, Client, String, String) {
+    let (dir, mut c, plate_top, tower_top_face, tower_edge, _vert) = setup_plate_and_tower_on(tag, plate);
